CREATE TABLE books (
  id INTEGER PRIMARY KEY,
  title TEXT,
  author TEXT,
  year INTEGER,
  price REAL
);
INSERT INTO books (id, title, author, year, price) VALUES
  (1, 'Matilda', 'Roald Dahl', 1988, 7.99),
  (2, 'Dune', 'Frank Herbert', 1965, 10.50),
  (3, 'The Hobbit', 'J. R. R. Tolkien', 1937, 8.25);
SELECT * FROM books;
INSERT INTO books (id, title, author, year, price) VALUES (2, 'Coraline', 'Neil Gaiman', 2002, 6.99);
SELECT COUNT(*) FROM books;

